func mergeFiltered(r *repo, paths []string) []string {
	if _, err := r.git("rev-parse", "-q", "--verify", "MERGE_HEAD"); err != nil {
		return paths
	}
	var kept []string
	for _, p := range paths {
		idx := blobOf(r, ":./"+p)
		head := blobOf(r, "HEAD:./"+p)
		mergeHead := blobOf(r, "MERGE_HEAD:./"+p)
		if idx != head && idx != mergeHead {
			kept = append(kept, p)
		}
	}
	return kept
}

